<?php
class Tokens
{
    public function truthy()
    {
        $bytes = openssl_random_pseudo_bytes(16, $strong);
        if ($bytes === false) {
            return null;
        }
        if ($strong) {
            return $bytes;
        }
        return null;
    }

    public function ternary()
    {
        $bytes = openssl_random_pseudo_bytes(16, $ok);
        return $bytes !== false && $ok ? $bytes : null;
    }

    public function loose()
    {
        $bytes = openssl_random_pseudo_bytes(16, $strong);
        if ($bytes === false || $strong == false) {
            return null;
        }
        return $bytes;
    }

    public function looseTrue()
    {
        $bytes = openssl_random_pseudo_bytes(16, $strong);
        if ($bytes === false || true != $strong) {
            return null;
        }
        return $bytes;
    }

    public function strictTrue()
    {
        $bytes = openssl_random_pseudo_bytes(16, $strong);
        if ($bytes === false || $strong !== true) {
            return null;
        }
        return $bytes;
    }

    public function strictTrueYoda()
    {
        $bytes = openssl_random_pseudo_bytes(16, $strong);
        if ($bytes === false || true === $strong) {
            return $bytes;
        }
        return null;
    }

    public function inlineCheck()
    {
        if (($bytes = openssl_random_pseudo_bytes(16, $strong)) === false || !$strong) {
            return null;
        }
        return $bytes;
    }

    public function inlineCheckYoda()
    {
        if (false !== ($raw = @mcrypt_create_iv(16, MCRYPT_DEV_RANDOM))) {
            return $raw;
        }
        return null;
    }

    public function inlineNegation()
    {
        if (!($bytes = <error descr="The generated bytes may be false; check the result.">openssl_random_pseudo_bytes</error>(16, $strong)) || !$strong) {
            return null;
        }
        return $bytes;
    }

    public function inlineLoose()
    {
        if (($bytes = <error descr="The generated bytes may be false; check the result.">openssl_random_pseudo_bytes</error>(16, $strong)) == false || !$strong) {
            return null;
        }
        return $bytes;
    }

    public function inlineOtherConstant()
    {
        if (null === ($bytes = <error descr="The generated bytes may be false; check the result.">openssl_random_pseudo_bytes</error>(16, $strong)) || !$strong) {
            return null;
        }
        return $bytes;
    }

    public function unchecked()
    {
        $bytes = openssl_random_pseudo_bytes(16, <error descr="The strength flag may be false; check it.">$strong</error>);
        if ($bytes === false || $strong == 1) {
            return null;
        }
        return [$bytes, $strong];
    }
}
